vehicle:
var all = Manager.GetVehicleList();
var models = all.Where(Ordinary).Select(v => v.prefab.name).Distinct().OrderBy(n => n, StringComparer.Ordinal).ToArray();
if (models.Length == 0) return false;
if (string.IsNullOrEmpty(citizen.Car.ModelId)) citizen.Car.ModelId = models[Hash(citizen.Car.Id) % (uint)models.Length];
if (citizen.Car.PaintSeed == 0) citizen.Car.PaintSeed = 1 + (int)(Hash(citizen.Car.Id + ":paint") % 2147483646u);
LastAdmissionStage = "inactive model slot";
var slot = all.FirstOrDefault(v => Ordinary(v) && !v.gameObject.activeInHierarchy && v.prefab.name == citizen.Car.ModelId);
if (slot == null || bodies.ContainsKey(slot.GetIndex())) return false; // Never invoke LoadVehicle's active-name fallback.
// LoadVehicle chooses the first inactive exact-prefab slot, including protected slots.
// Reject that ordering conflict rather than activate a service body and roll it back later.
var nativeChoice = all.FirstOrDefault(v => v != null && ReferenceEquals(v.prefab, slot.prefab) && !v.gameObject.activeInHierarchy);
if (!ReferenceEquals(nativeChoice, slot)) return false;

ordinary:
internal static bool Ordinary(VehicleComponent vehicle) => vehicle != null && vehicle.vehicleType == VehicleTypes.Car && RandomAmbient(vehicle);
internal static bool RandomAmbient(VehicleComponent vehicle)
{
    // Both native Car and Truck enum values can be ordinary ambient traffic. Model eligibility
    // for citizen cars remains narrower; a truck must not become a protected service by its enum.
    if (vehicle == null || vehicle.prefab == null) return false;
    // Component ownership, not model names: never borrow a service/taxi instance.
    return vehicle.GetComponentInChildren<TaxiController>(true) == null
        && vehicle.GetComponentInChildren<PrivateDriverVehicle>(true) == null
        && vehicle.GetComponentInChildren<VehicleController>(true) == null
        && VehicleScriptOwnership.NativeOnly(vehicle);
}

selection:
foreach (var candidate in simulation.State.Citizens.Where(c => c.NextEventMinute > simulation.State.Minute
        && !bindings.ContainsKey(c.Identity.Id) && !ambient.IsReserved(c.Identity.Id)
        && (!attempted.TryGetValue(c.Identity.Id, out float at) || Time.unscaledTime - at >= 2))
    .Select(c => (Citizen: c, Position: simulation.PositionOf(c)))
    .Where(c => Position.Distance(c.Position, focus) <= radius)
    .OrderBy(c => attempted.TryGetValue(c.Citizen.Identity.Id, out float at) ? at : float.NegativeInfinity)
    .ThenBy(c => Position.Distance(c.Position, focus)).ThenBy(c => c.Citizen.Identity.Id, StringComparer.Ordinal))
{
    var citizen = candidate.Citizen;
    bool moving = citizen.Phase == CitizenPhase.Travelling && citizen.Journey != null;
    PhysicalJourneySample sample = moving ? simulation.SampleJourney(citizen) : default;
    bool car = moving && sample.Mode == TravelMode.Car && !sample.Stationary;
    QueuePlanEntry? queue = null;
    bool queuer = !moving && queuers.TryGetValue(citizen.Identity.Id, out queue);
    bool person = moving ? sample.Mode == TravelMode.Walk : queuer || Outdoor(citizen);
    if ((!car && !person) || (car ? cars >= vehicleLimit : people >= pedestrianLimit)) continue;
    if (++attempts > 4) break; // Route validation and rejected admissions share the native-work budget.
    attempted[citizen.Identity.Id] = Time.unscaledTime;

sample:
internal static PhysicalJourneySample SampleRoute(Route route, double routeElapsedMinutes, Position? parkedCar)
{
    if (!Position.Finite(routeElapsedMinutes) || routeElapsedMinutes < 0 || routeElapsedMinutes > route.Minutes)
        throw new ArgumentOutOfRangeException(nameof(routeElapsedMinutes));
    double remaining = routeElapsedMinutes;
    double sampledElapsed = routeElapsedMinutes;
    Position? car = parkedCar;
    for (int i = 0; i < route.Legs.Count; i++)
    {
        var leg = route.Legs[i];
        // Summing fractional legs and then subtracting them can leave an endpoint a few
        // ulps short. Snap only a negligible fraction of this leg, so a reached corner
        // cannot remain leased forever while the native body has already stopped there.
        double boundaryTolerance = Math.Min(leg.Minutes * 1e-9, Math.Max(1e-12, Math.Abs(routeElapsedMinutes) * 1e-14));
        if (Math.Abs(remaining - leg.Minutes) <= boundaryTolerance)
        {
            // Endpoint normalization may move the geometry back by a few ulps when the
            // measured progress was just beyond the corner. Never move its clock back.
            sampledElapsed = Math.Max(routeElapsedMinutes, sampledElapsed + leg.Minutes - remaining);
            remaining = leg.Minutes;
        }
        // At a boundary, expose the next leg (important for walk/car/transit handoffs).
        if (remaining < leg.Minutes || i == route.Legs.Count - 1)
        {
            double fraction = Math.Min(1, remaining / leg.Minutes);
            var position = Position.Lerp(leg.From, leg.To, fraction);
            if (leg.Mode == TravelMode.Car) car = position;
            return new PhysicalJourneySample(i == route.Legs.Count - 1 && fraction == 1 ? route.Minutes : Math.Min(route.Minutes, Math.Max(routeElapsedMinutes, sampledElapsed)), route.Minutes, i, fraction, leg, position, car, i + 1 < route.Legs.Count ? route.Legs[i + 1].Mode : (TravelMode?)null);
        }
        if (leg.Mode == TravelMode.Car) car = leg.To;
        remaining -= leg.Minutes;
    }
    throw new InvalidOperationException("Invalid route.");
}
